@push('scripts')<script>
$(function(){
 const modal=new bootstrap.Modal('#equipmentIssueModal'), productModal=new bootstrap.Modal('#equipmentIssueProductModal');
 const table=$('#equipmentIssueTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:{url:@json(route('super.equipment-issues.dt')),data:d=>{d.from_date=$('#issueFrom').val();d.to_date=$('#issueTo').val()}},columns:[{data:'id',orderable:false,searchable:false,render:(d,t,r,m)=>m.row+m.settings._iDisplayStart+1},{data:'actions',orderable:false,searchable:false},{data:'number',name:'number'},{data:'date_label',name:'issue_date'},{data:'item_code',orderable:false,searchable:false},{data:'item_name',orderable:false,searchable:false},{data:'unit',orderable:false,searchable:false},{data:'quantity',orderable:false,searchable:false},{data:'description',orderable:false,searchable:false}],order:[[3,'desc']],drawCallback:()=>window.feather&&feather.replace()});
 const products=$('#equipmentIssueProducts').DataTable({processing:true,serverSide:true,ajax:@json(route('super.equipment-issues.products.dt')),columns:[{data:'code',name:'code'},{data:'name',name:'name'},{data:'category_label',orderable:false,searchable:false},{data:'unit_label',orderable:false,searchable:false},{data:'actions',orderable:false,searchable:false}]});
 function reset(){ $('#equipmentIssueForm')[0].reset();$('#equipmentIssueId,#equipmentIssueProductId').val('');$('#equipmentIssueCode,#equipmentIssueName,#equipmentIssueUnit').val('');$('#equipmentIssueDate').val(@json(now()->toDateString()));$('#equipmentIssueTitle').text(@json(__('ui.machine_issue.add')));$('#equipmentIssueNumber').val(@json(__('ui.scrap_receipt.number_loading')));$.get(@json(route('super.equipment-issues.number-preview'))).done(r=>$('#equipmentIssueNumber').val(r.number)); }
 $('#addEquipmentIssue').on('click',()=>{reset();modal.show()});$('#chooseEquipmentIssueProduct').on('click',()=>productModal.show());$('#showIssue').on('click',()=>table.ajax.reload());$('#issueFrom,#issueTo').on('change',()=>table.ajax.reload());
 $('#exportIssue').on('click',function(e){e.preventDefault();location.href=this.href+'?'+$.param({from_date:$('#issueFrom').val(),to_date:$('#issueTo').val()})});
 $(document).on('click','.btn-select-equipment-issue-product',function(){const b=$(this);$('#equipmentIssueProductId').val(b.data('id'));$('#equipmentIssueCode').val(b.data('code'));$('#equipmentIssueName').val(b.data('name'));$('#equipmentIssueUnit').val(b.data('unit'));productModal.hide()});
 $(document).on('click','.btn-edit-equipment-issue',function(){const id=$(this).data('id');$.get(@json(route('super.equipment-issues.show',['equipmentIssue'=>'__ID__'])).replace('__ID__',id)).done(d=>{reset();$('#equipmentIssueId').val(d.id);$('#equipmentIssueNumber').val(d.number);$('#equipmentIssueDate').val(d.issue_date);$('#equipmentIssueCode').val(d.item?.item_code||'');$('#equipmentIssueName').val(d.item?.item_name||'');$('#equipmentIssueUnit').val(d.item?.unit||'');$('#equipmentIssueProductId').val(d.item?.product_id||'');$('#equipmentIssueQuantity').val(d.item?.quantity||'');$('#equipmentIssueDescription').val(d.item?.description||'');$('#equipmentIssueTitle').text(@json(__('ui.common.edit'))+' {{ __('ui.machine_issue.title') }}');modal.show()})});
 $(document).on('click','.btn-delete-equipment-issue',function(){const id=$(this).data('id');Swal.fire({icon:'warning',title:@json(__('ui.common.confirm_delete')),showCancelButton:true,confirmButtonText:@json(__('ui.common.delete')),cancelButtonText:@json(__('ui.common.cancel'))}).then(r=>{if(r.isConfirmed)$.ajax({url:@json(route('super.equipment-issues.destroy',['equipmentIssue'=>'__ID__'])).replace('__ID__',id),method:'DELETE',data:{_token:@json(csrf_token())}}).done(x=>{table.ajax.reload(null,false);Swal.fire({icon:'success',text:x.message})}).fail(x=>Swal.fire({icon:'error',text:x.responseJSON?.message||@json(__('ui.workflow.save_failed'))}))})});
 $('#equipmentIssueForm').on('submit',function(e){e.preventDefault();const id=$('#equipmentIssueId').val(),url=id?@json(route('super.equipment-issues.update',['equipmentIssue'=>'__ID__'])).replace('__ID__',id):@json(route('super.equipment-issues.store'));$.ajax({url,method:id?'PUT':'POST',data:$(this).serialize()}).done(r=>{modal.hide();table.ajax.reload(null,false);Swal.fire({icon:'success',text:`${r.message} (${r.number})`})}).fail(x=>Swal.fire({icon:'error',title:@json(__('ui.workflow.failure')),text:Object.values(x.responseJSON?.errors||{}).flat().join('\n')||x.responseJSON?.message||@json(__('ui.workflow.save_failed'))}))});
});
</script>@endpush
